func (a *Agent) fenceTerraBaseMember(ctx context.Context, role string) (stopped bool, err error) {
	if !a.cfg.TerraBaseDataVolume || role != terrabase.Role {
		return false, nil
	}
	lost := a.terraBaseDataVolumeIntact()
	if lost == nil {
		return false, nil
	}
	a.terraBaseVolumeConfirmed = ""
	current, observeErr := a.runner.Observe(ctx, role)
	if observeErr == nil && !current.Running {
		return false, nil
	}
	if err := a.runner.Stop(ctx, role); err != nil {
		return false, errors.Join(fmt.Errorf("stop the terrabase member: data volume: %w", lost), observeErr, err)
	}
	delete(a.terraBase, role)
	slog.WarnContext(ctx, "terrabase member stopped: its data volume is not intact", "error", lost)
	return true, nil
}

func (a *Agent) terraBaseDataVolumeIntact() error {
	if err := verifyDataMount(terrabase.Layout(a.cfg.TerraBaseRoot).Data(), a.cfg.WorkloadIdentity); err != nil {
		return err
	}
	uuid, err := dataFilesystemUUID()
	if err != nil {
		return err
	}
	if a.terraBaseVolumeConfirmed == "" || uuid != a.terraBaseVolumeConfirmed {
		return fmt.Errorf("data volume holds ext4 %s, not the confirmed %q", uuid, a.terraBaseVolumeConfirmed)
	}
	return nil
}

func verifyTerraBaseDataMount(data string, identity WorkloadIdentity) error {
	device, err := managedBlockDevice(oci.MemberVolumeDevice)
	if err != nil {
		return fmt.Errorf("data volume %s is not attached: %w", oci.MemberVolumeDevice, err)
	}
	defer device.close()
	info, err := os.Lstat(data)
	if err != nil {
		return err
	}
	owner, ok := info.Sys().(*syscall.Stat_t)
	if !ok || !info.IsDir() || owner.Dev != device.stat.Rdev || owner.Uid != identity.UID ||
		owner.Gid != identity.GID || info.Mode().Perm() != 0o700 {
		return fmt.Errorf("%s is not the workload-owned data volume", data)
	}
	mountID, err := findExclusiveMount("/proc/self/mountinfo", data, device.stat.Rdev, storage.FileSystemExt4)
	if err != nil {
		return err
	}
	return hostvolume.RequireHardened("/proc/self/mountinfo", mountID)
}

func managedBlockDevice(devicePath string) (*managedDevice, error) {
	resolved := devicePath
	ancestors, err := managedDeviceAncestors(devicePath)
	if err != nil {
		return nil, err
	}
	for _, directory := range ancestors {
		info, err := os.Lstat(directory)
		if err != nil {
			return nil, err
		}
		owner, ok := info.Sys().(*syscall.Stat_t)
		if !ok || !validManagedDeviceAncestor(info.Mode(), owner) {
			return nil, errors.New("managed device ancestor is writable or untrusted")
		}
	}
	if len(ancestors) == 2 {
		info, err := os.Lstat(devicePath)
		if err != nil {
			return nil, err
		}
		owner, ok := info.Sys().(*syscall.Stat_t)
		if !ok || info.Mode()&os.ModeSymlink == 0 || owner.Uid != 0 {
			return nil, errors.New("OCI device alias is not a root-owned symlink")
		}
		target, err := os.Readlink(devicePath)
		if err != nil {
			return nil, err
		}
		resolved, err = oracleOCIAliasTarget(devicePath, target)
		if err != nil {
			return nil, err
		}
	}
	info, err := os.Lstat(resolved)
	if err != nil {
		return nil, err
	}
	device, ok := info.Sys().(*syscall.Stat_t)
	if !ok || info.Mode()&os.ModeDevice == 0 || info.Mode()&os.ModeCharDevice != 0 ||
		info.Mode()&os.ModeSymlink != 0 || device.Uid != 0 {
		return nil, errors.New("managed device is not an exact root-owned block device")
	}
	fd, err := unix.Open(resolved, unix.O_PATH|unix.O_NOFOLLOW|unix.O_CLOEXEC, 0)
	if err != nil {
		return nil, err
	}
	var opened syscall.Stat_t
	if err := syscall.Fstat(fd, &opened); err != nil {
		_ = unix.Close(fd)
		return nil, err
	}
	if opened.Mode&syscall.S_IFMT != syscall.S_IFBLK || opened.Uid != 0 || opened.Rdev != device.Rdev {
		_ = unix.Close(fd)
		return nil, errors.New("opened managed block device differs from signed alias target")
	}
	return &managedDevice{fd: fd, stat: opened}, nil
}

func managedDeviceAncestors(path string) ([]string, error) {
	switch filepath.Dir(path) {
	case "/dev":
		return []string{"/dev"}, nil
	case "/dev/oracleoci":
		return []string{"/dev", "/dev/oracleoci"}, nil
	default:
		return nil, errors.New("managed block device must be a direct /dev node or OCI alias")
	}
}

func validManagedDeviceAncestor(mode os.FileMode, owner *syscall.Stat_t) bool {
	return owner != nil && mode.IsDir() && mode&os.ModeSymlink == 0 && owner.Uid == 0 && mode.Perm()&0022 == 0
}

func (a *Agent) terraBaseRunningReport(ctx context.Context, d Desired) Report {
	// Publication rechecks the cached observation's freshness and exact process while this poll runs.
	// reconcile fenced a member whose data volume is gone before it got
	// here; these checks stop it when the volume goes between the two or
	// while preparation renews the certificate and maintains the mount.
	if stopped, err := a.fenceTerraBaseMember(ctx, d.Role); stopped || err != nil {
		return a.reportFor(d, "failed", errors.Join(errors.New("terrabase data volume is not intact"), err))
	}
	_, _, renewErr := a.prepareTerraBase(ctx, d)
	if stopped, err := a.fenceTerraBaseMember(ctx, d.Role); stopped || err != nil {
		return a.reportFor(d, "failed", errors.Join(errors.New("terrabase data volume is not intact"), renewErr, err))
	}
	// ponytail: a per-node offset of one to seven days keeps the members of
	// a cell that cannot reload from restarting together.
	restartBefore := time.Duration(24+crc32.ChecksumIEEE([]byte(a.cfg.Node))%144) * time.Hour
	member := a.terraBase[d.Role]
	if renewErr == nil && !member.certificateExpiry.IsZero() && time.Until(member.certificateExpiry) < restartBefore {
		served, err := a.terraBaseServedExpiry(ctx, d)
		if err != nil || time.Until(served) < restartBefore {
			stopErr := a.runner.Stop(ctx, d.Role)
			if stopErr == nil {
				delete(a.terraBase, d.Role)
			}
			return a.reportFor(d, "starting", errors.Join(errors.New("restarting to load the renewed member certificate"),
				err, stopErr))
		}
		member.certificateExpiry = served
		a.terraBase[d.Role] = member
	}
	state, healthErr := a.terraBaseState(ctx, d)
	if state == "running" {
		a.collectTerraBaseWAN(ctx, d)
	}
	return a.reportFor(d, state, errors.Join(healthErr, renewErr))
}

func (m *memoryRunner) Stop(_ context.Context, role string) error {
	m.mu.Lock()
	defer m.mu.Unlock()
	delete(m.observed, role)
	return nil
}

func (m *memoryRunner) Observe(_ context.Context, role string) (Observation, error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	return m.observed[role], nil
}

func (a *Agent) reportFor(d Desired, state string, failure error) Report {
	a.mu.RLock()
	s := a.session
	a.mu.RUnlock()
	r := Report{Cell: a.cfg.Cell, Node: a.cfg.Node, Environment: a.cfg.Environment, Role: d.Role, Digest: d.Digest, Generation: d.Generation, SessionID: s.SessionID, Epoch: s.Epoch, State: state, ObservedAt: time.Now().UTC()}
	if failure != nil {
		r.Error = failure.Error()
	}
	return r
}

