func fakeDataVolume(t *testing.T, mounted *bool, uuid *string) (recorded *string, confirms *int) {
	t.Helper()
	recorded, confirms = new(string), new(int)
	verify, filesystem, confirm := verifyDataMount, dataFilesystemUUID, confirmDataFilesystem
	t.Cleanup(func() { verifyDataMount, dataFilesystemUUID, confirmDataFilesystem = verify, filesystem, confirm })
	verifyDataMount = func(string, WorkloadIdentity) error {
		if !*mounted {
			return errors.New("not mounted")
		}
		return nil
	}
	dataFilesystemUUID = func() (string, error) { return *uuid, nil }
	confirmDataFilesystem = func(_ context.Context, _ *Agent, mounted string) (string, error) {
		*confirms++
		if *recorded == "" {
			*recorded = mounted
		}
		return *recorded, nil
	}
	return recorded, confirms
}

func (a *Agent) establishTerraBaseDataVolume(ctx context.Context) error {
	data := terrabase.Layout(a.cfg.TerraBaseRoot).Data()
	if verifyDataMount(data, a.cfg.WorkloadIdentity) == nil {
		if time.Since(a.terraBaseVolumeChecked) < terraBaseVolumeRecheck {
			return nil
		}
		// The mount is in place, so maintenance is best effort, and bounded:
		// the member is fenced again only after it returns.
		a.terraBaseVolumeChecked = time.Now()
		maintenance, cancel := context.WithTimeout(ctx, terraBaseMaintenanceTimeout)
		defer cancel()
		if err := requestTerraBaseDataVolume(maintenance, a.cfg.VolumeInitSocket, nil); err != nil {
			slog.WarnContext(maintenance, "terrabase data volume maintenance failed", "error", err)
		}
		return verifyDataMount(data, a.cfg.WorkloadIdentity)
	}
	err := requestTerraBaseDataVolume(ctx, a.cfg.VolumeInitSocket, nil)
	if needed, ok := errors.AsType[terraBaseFormatNeeded](err); ok {
		// Retry the same durable initializer attempt; issuing a response does
		// not consume it. The helper consumes it durably immediately before mkfs.
		var reply terraBaseFormatReply
		var grant protocol.Envelope
		if _, err = a.sendToLeader(ctx, "terrabase-format", terraBaseFormatQuery{VolumeID: a.cfg.TerraBaseDataVolumeID, AttemptID: needed.AttemptID}, &reply, &grant, nil); err == nil {
			err = requestTerraBaseDataVolume(ctx, a.cfg.VolumeInitSocket, &grant)
		}
	}
	if err != nil {
		return fmt.Errorf("terrabase data volume is not mounted: %w", err)
	}
	if err := verifyDataMount(data, a.cfg.WorkloadIdentity); err != nil {
		return fmt.Errorf("terrabase data volume mount readback: %w", err)
	}
	a.terraBaseVolumeChecked = time.Now()
	return nil
}

func requestTerraBaseDataVolume(ctx context.Context, socket string, grant *protocol.Envelope) error {
	wire := terraBaseDataRequest
	if grant != nil {
		encoded, err := protocol.EncodeJSON(*grant)
		if err != nil {
			return err
		}
		wire = slices.Concat(terraBaseDataRequest, []byte("\n"), encoded)
	}
	if socket == "" {
		socket = volumeInitSocketPath
	}
	connection, err := (&net.Dialer{Timeout: 5 * time.Second}).DialContext(ctx, "unix", socket)
	if err != nil {
		return fmt.Errorf("connect fixed volume initializer: %w", err)
	}
	defer connection.Close()
	stop := context.AfterFunc(ctx, func() { _ = connection.Close() })
	defer stop()
	// The first mount may format the whole volume.
	if err := connection.SetDeadline(time.Now().Add(20 * time.Minute)); err != nil {
		return err
	}
	if err := exchangeVolumeInit(connection, wire); err != nil {
		if errors.Is(err, errFormatGrantNeeded) {
			return err
		}
		return fmt.Errorf("volume initializer did not mount %s; its journal has the cause: %w", oci.MemberVolumeDevice, err)
	}
	return nil
}

func exchangeVolumeInit(connection net.Conn, wire []byte) error {
	var size [4]byte
	binary.BigEndian.PutUint32(size[:], uint32(len(wire)))
	if _, err := connection.Write(size[:]); err != nil {
		return err
	}
	if _, err := connection.Write(wire); err != nil {
		return err
	}
	var result [1]byte
	if _, err := io.ReadFull(connection, result[:]); err != nil {
		return err
	}
	switch result[0] {
	case 0:
		return nil
	case volumeInitNeedsGrant:
		var attempt [26]byte
		if _, err := io.ReadFull(connection, attempt[:]); err != nil {
			return err
		}
		if !entityid.Valid(string(attempt[:])) {
			return errors.New("volume initializer returned an invalid first-format attempt")
		}
		return terraBaseFormatNeeded{AttemptID: string(attempt[:])}
	}
	return errors.New("volume initializer refused the request")
}

func (a *Agent) terraBaseRunningReport(ctx context.Context, d Desired) Report {
	// Publication rechecks the cached observation's freshness and exact process while this poll runs.
	// reconcile fenced a member whose data volume is gone before it got
	// here; these checks stop it when the volume goes between the two or
	// while preparation renews the certificate and maintains the mount.
	if stopped, err := a.fenceTerraBaseMember(ctx, d.Role); stopped || err != nil {
		return a.reportFor(d, "failed", errors.Join(errors.New("terrabase data volume is not intact"), err))
	}
	_, _, renewErr := a.prepareTerraBase(ctx, d)
	if stopped, err := a.fenceTerraBaseMember(ctx, d.Role); stopped || err != nil {
		return a.reportFor(d, "failed", errors.Join(errors.New("terrabase data volume is not intact"), renewErr, err))
	}
	// ponytail: a per-node offset of one to seven days keeps the members of
	// a cell that cannot reload from restarting together.
	restartBefore := time.Duration(24+crc32.ChecksumIEEE([]byte(a.cfg.Node))%144) * time.Hour
	member := a.terraBase[d.Role]
	if renewErr == nil && !member.certificateExpiry.IsZero() && time.Until(member.certificateExpiry) < restartBefore {
		served, err := a.terraBaseServedExpiry(ctx, d)
		if err != nil || time.Until(served) < restartBefore {
			stopErr := a.runner.Stop(ctx, d.Role)
			if stopErr == nil {
				delete(a.terraBase, d.Role)
			}
			return a.reportFor(d, "starting", errors.Join(errors.New("restarting to load the renewed member certificate"),
				err, stopErr))
		}
		member.certificateExpiry = served
		a.terraBase[d.Role] = member
	}
	state, healthErr := a.terraBaseState(ctx, d)
	if state == "running" {
		a.collectTerraBaseWAN(ctx, d)
	}
	return a.reportFor(d, state, errors.Join(healthErr, renewErr))
}

func (a *Agent) prepareTerraBase(ctx context.Context, d Desired) (map[string]string, time.Time, error) {
	if len(d.Args) != 0 {
		// The binary lets an argument override the host-owned settings.
		return nil, time.Time{}, errors.New("terrabase members take no arguments")
	}
	profile, err := terrabase.ParseProfile(d.Env)
	if err != nil {
		return nil, time.Time{}, err
	}
	peer, listed := a.terraBasePeer(profile)
	if !listed {
		return nil, time.Time{}, fmt.Errorf("node %s is not in %s", a.cfg.Node, terrabase.EnvPeers)
	}
	// Recheck the ancestors right before the privileged effects below.
	if err := validateTerraBaseRoot(a.cfg.TerraBaseRoot, a.cfg.InstallRoot, a.cfg.StateRoot, a.cfg.WorkloadIdentity); err != nil {
		return nil, time.Time{}, err
	}
	layout := terrabase.Layout(a.cfg.TerraBaseRoot)
	supervisor, uid, gid := os.Geteuid(), int(a.cfg.WorkloadIdentity.UID), int(a.cfg.WorkloadIdentity.GID)
	// The binary writes its databases and extracted libraries; it only
	// reads its TLS material, which stays supervisor-owned.
	type ownedDir struct {
		path     string
		uid, gid int
		mode     os.FileMode
	}
	dirs := []ownedDir{{string(layout), supervisor, gid, 0o750}, {layout.TLS(), supervisor, gid, 0o750},
		{layout.Bundle(), uid, gid, 0o700}}
	if !a.cfg.TerraBaseDataVolume {
		dirs = append(dirs, ownedDir{layout.Data(), uid, gid, 0o700})
	}
	for _, dir := range dirs {
		if err := ensureOwnedDir(dir.path, dir.uid, dir.gid, dir.mode); err != nil {
			return nil, time.Time{}, err
		}
	}
	// The volume initializer owns a data volume mount; never fall back to
	// the boot disk without one.
	if a.cfg.TerraBaseDataVolume {
		// Artifact and controller requests may have outlasted the caller's
		// fence. Stop any remaining writer before repairing a lost mount.
		if _, err := a.fenceTerraBaseMember(ctx, d.Role); err != nil {
			return nil, time.Time{}, err
		}
		if err := a.ensureTerraBaseDataVolume(ctx); err != nil {
			return nil, time.Time{}, err
		}
	}
	// The member's private key never reaches disk (TS-745).
	if a.cfg.MemoryRuntime {
		if err := vaultsecret.RequireMemoryFilesystem(layout.TLS()); err != nil {
			return nil, time.Time{}, err
		}
	}
	key, err := os.ReadFile(layout.Key())
	if errors.Is(err, os.ErrNotExist) {
		if key, _, err = terrabase.NewMemberKey(); err == nil {
			err = writeOwnedFile(layout.Key(), key, gid)
		}
	}
	if err != nil {
		return nil, time.Time{}, err
	}
	certificate, _ := os.ReadFile(layout.Certificate())
	ca, _ := os.ReadFile(layout.CA())
	if !terrabase.CurrentCertificate(certificate, key, ca, peer, time.Now()) {
		csr, err := terrabase.CertificateRequest(key)
		if err != nil {
			return nil, time.Time{}, err
		}
		var reply terraBasePeerReply
		if err := a.request(ctx, "terrabase-peer", terraBasePeerQuery{CSR: csr}, &reply); err != nil {
			return nil, time.Time{}, err
		}
		if !terrabase.CurrentCertificate(reply.Certificate, key, reply.CA, peer, time.Now()) {
			return nil, time.Time{}, errors.New("controller returned an unusable TerraBase member certificate")
		}
		if err := writeOwnedFile(layout.CA(), reply.CA, gid); err != nil {
			return nil, time.Time{}, err
		}
		if err := writeOwnedFile(layout.Certificate(), reply.Certificate, gid); err != nil {
			return nil, time.Time{}, err
		}
		certificate = reply.Certificate
	}
	return layout.Env(d.Env, profile, peer.Name), terrabase.CertificateExpiry(certificate), nil
}

func (a *Agent) terraBasePeer(profile terrabase.Profile) (terrabase.Peer, bool) {
	if peer, ok := profile.Peer(a.cfg.Node); ok {
		return peer, true
	}
	for _, peer := range profile.Peers {
		if a.ownAddress(peer.Address) {
			return peer, true
		}
	}
	return terrabase.Peer{}, false
}

func validateWorkloadRoot(name, root string, identity WorkloadIdentity, others ...string) error {
	separator := string(filepath.Separator)
	for _, other := range others {
		if other != "" && (root == other || strings.HasPrefix(root, other+separator) || strings.HasPrefix(other, root+separator)) {
			return errors.New(name + " root must be separate from the install, state and other workload roots")
		}
	}
	if !filepath.IsAbs(root) || filepath.Clean(root) != root || root == separator {
		return errors.New(name + " root must be a clean absolute path other than /")
	}
	// Only the workload root may be absent; every parent must already be safe.
	if err := inspectWorkloadPath(filepath.Dir(root), identity, true, false, false); err != nil {
		return fmt.Errorf("%s root parent: %w", name, err)
	}
	// Every existing component is a real, non-replaceable directory...
	if err := inspectWorkloadPath(root, identity, true, true, false); err != nil {
		return fmt.Errorf("%s root: %w", name, err)
	}
	// ...and the workload cannot create the root before the agent does, not
	// even in a sticky parent such as /tmp.
	if info, err := os.Lstat(filepath.Dir(root)); err == nil && identity.UID != uint32(os.Geteuid()) {
		owner, _ := info.Sys().(*syscall.Stat_t)
		write := info.Mode().Perm() & 0o002
		if owner != nil && owner.Gid == identity.GID {
			write = info.Mode().Perm() & 0o020
		}
		if owner != nil && owner.Uid == identity.UID {
			write = info.Mode().Perm() & 0o200
		}
		if write != 0 {
			return errors.New("the workload identity can create entries next to the " + name + " root")
		}
	}
	// ...so the path resolves to itself.
	existing := root
	for {
		if _, err := os.Lstat(existing); err == nil {
			break
		}
		existing = filepath.Dir(existing)
	}
	if resolved, err := filepath.EvalSymlinks(existing); err != nil || resolved != existing {
		return fmt.Errorf("%s root %s does not resolve to itself", name, existing)
	}
	return nil
}

func ensureOwnedDir(path string, uid, gid int, mode os.FileMode) error {
	if err := os.Mkdir(path, mode); err != nil && !errors.Is(err, os.ErrExist) {
		return err
	}
	fd, err := unix.Open(path, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_NOFOLLOW|unix.O_CLOEXEC, 0)
	if err != nil {
		return fmt.Errorf("%s must be a directory, not a symlink: %w", path, err)
	}
	defer unix.Close(fd)
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil {
		return err
	}
	if int(stat.Uid) == uid && int(stat.Gid) == gid && stat.Mode&0o7777 == uint32(mode.Perm()) {
		return nil
	}
	if err := unix.Fchown(fd, os.Geteuid(), gid); err != nil {
		return err
	}
	if err := unix.Fchmod(fd, uint32(mode.Perm())); err != nil {
		return err
	}
	return unix.Fchown(fd, uid, gid)
}

func ParseProfile(env map[string]string) (Profile, error) {
	for _, key := range hostOwned {
		if _, set := env[key]; set {
			return Profile{}, fmt.Errorf("terrabase profile must not set %s", key)
		}
	}
	profile := Profile{AdminPort: DefaultAdminPort}
	var err error
	if raw, set := env[EnvAdminPort]; set {
		if profile.AdminPort, err = parsePort(raw); err != nil {
			return Profile{}, fmt.Errorf("%s: %w", EnvAdminPort, err)
		}
	}
	if profile.PeerPort, err = parsePort(env[EnvPeerPort]); err != nil {
		return Profile{}, fmt.Errorf("%s: %w", EnvPeerPort, err)
	}
	if raw, set := env[EnvClientPort]; set {
		if profile.ClientPort, err = parsePort(raw); err != nil {
			return Profile{}, fmt.Errorf("%s: %w", EnvClientPort, err)
		}
	}
	if profile.Peers, err = ParsePeers(env[EnvPeers]); err != nil {
		return Profile{}, err
	}
	for _, peer := range profile.Peers {
		if int(peer.Address.Port()) != profile.PeerPort {
			return Profile{}, fmt.Errorf("%s: peer %s does not use %s", EnvPeers, peer.Name, EnvPeerPort)
		}
	}
	if profile.AdminPort == profile.PeerPort || profile.ClientPort == profile.AdminPort || profile.ClientPort == profile.PeerPort {
		return Profile{}, errors.New("terrabase admin, peer and client ports must differ")
	}
	return profile, nil
}

func (p Profile) Peer(node string) (Peer, bool) {
	index := slices.IndexFunc(p.Peers, func(peer Peer) bool { return peer.Name == node })
	if index < 0 {
		return Peer{}, false
	}
	return p.Peers[index], true
}

func traversableTempDir(t *testing.T) string {
	t.Helper()
	dir, err := os.MkdirTemp("/tmp", "ts-terrabase-root-")
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = os.RemoveAll(dir) })
	if err := os.Chmod(dir, 0o755); err != nil {
		t.Fatal(err)
	}
	return dir
}

func testAgentIdentity() WorkloadIdentity {
	if os.Geteuid() == 0 {
		return WorkloadIdentity{UID: 65534, GID: 65534}
	}
	return WorkloadIdentity{UID: uint32(os.Getuid()), GID: uint32(os.Getgid())}
}

func (a *Agent) reportFor(d Desired, state string, failure error) Report {
	a.mu.RLock()
	s := a.session
	a.mu.RUnlock()
	r := Report{Cell: a.cfg.Cell, Node: a.cfg.Node, Environment: a.cfg.Environment, Role: d.Role, Digest: d.Digest, Generation: d.Generation, SessionID: s.SessionID, Epoch: s.Epoch, State: state, ObservedAt: time.Now().UTC()}
	if failure != nil {
		r.Error = failure.Error()
	}
	return r
}

