func workloadOwnedDir(t *testing.T, mode os.FileMode) string {
	t.Helper()
	if os.Geteuid() != 0 {
		t.Skip("needs root to own a directory as another user")
	}
	dir := filepath.Join(t.TempDir(), "owned")
	if err := os.Mkdir(dir, mode); err != nil {
		t.Fatal(err)
	}
	if err := os.Chown(dir, 2000, 2000); err != nil {
		t.Fatal(err)
	}
	return dir
}

func withCapabilities(t *testing.T, keep []uint, fn func() error) error {
	t.Helper()
	result := make(chan error, 1)
	go func() {
		runtime.LockOSThread()
		var mask [2]uint32
		for _, capability := range keep {
			mask[capability/32] |= 1 << (capability % 32)
		}
		header := unix.CapUserHeader{Version: unix.LINUX_CAPABILITY_VERSION_3}
		data := [2]unix.CapUserData{{Effective: mask[0], Permitted: mask[0]}, {Effective: mask[1], Permitted: mask[1]}}
		if err := unix.Capset(&header, &data[0]); err != nil {
			result <- err
			return
		}
		result <- fn()
	}()
	return <-result
}

func requireOwned(t *testing.T, dir string, id uint32, mode os.FileMode) {
	t.Helper()
	info, err := os.Stat(dir)
	if err != nil {
		t.Fatal(err)
	}
	owner := info.Sys().(*syscall.Stat_t)
	if owner.Uid != id || owner.Gid != id || info.Mode().Perm() != mode {
		t.Fatalf("%s is %d:%d %v, want %d:%d %v", dir, owner.Uid, owner.Gid, info.Mode().Perm(), id, id, mode)
	}
}

func ownTerraBaseDataRoot(target string, rdev uint64, identity WorkloadIdentity) error {
	fd, err := unix.Open(target, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_NOFOLLOW|unix.O_CLOEXEC, 0)
	if err != nil {
		return err
	}
	defer unix.Close(fd)
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil {
		return err
	}
	if stat.Dev != rdev {
		return errors.New("data directory is not the data volume root")
	}
	if stat.Uid == identity.UID && stat.Gid == identity.GID && stat.Mode&0o7777 == 0o700 {
		return nil
	}
	if err := unix.Fchown(fd, 0, 0); err != nil {
		return err
	}
	if err := unix.Fchmod(fd, 0o700); err != nil {
		return err
	}
	if err := unix.Fchown(fd, int(identity.UID), int(identity.GID)); err != nil {
		return err
	}
	return unix.Syncfs(fd)
}

func emptyMountTarget(target string) error {
	if err := os.Mkdir(target, 0o700); err != nil && !errors.Is(err, os.ErrExist) {
		return err
	}
	fd, err := unix.Open(target, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_NOFOLLOW|unix.O_CLOEXEC, 0)
	if err != nil {
		return fmt.Errorf("%s must be a directory, not a symlink: %w", target, err)
	}
	defer unix.Close(fd)
	entries, err := os.ReadDir(fmt.Sprintf("/proc/self/fd/%d", fd))
	if err != nil {
		return err
	}
	if len(entries) != 0 {
		return fmt.Errorf("%s holds boot disk files; move them before the data volume is mounted there", target)
	}
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil {
		return err
	}
	if stat.Uid == 0 && stat.Gid == 0 && stat.Mode&0o7777 == 0o700 {
		return nil
	}
	// Without CAP_FOWNER the initializer takes the directory first.
	if err := unix.Fchown(fd, 0, 0); err != nil {
		return err
	}
	return unix.Fchmod(fd, 0o700)
}

