func TestHostRequestSendsTheTraceparent(t *testing.T) {
	srv, err := server.NewServer(&server.Options{Host: "127.0.0.1", Port: -1, NoLog: true, NoSigs: true})
	if err != nil {
		t.Fatal(err)
	}
	go srv.Start()
	if !srv.ReadyForConnections(5 * time.Second) {
		t.Fatal("NATS did not start")
	}
	t.Cleanup(func() { srv.Shutdown(); srv.WaitForShutdown() })
	conn, err := nats.Connect(srv.ClientURL())
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(conn.Close)

	ctx, cancel := context.WithCancel(observability.StartTrace(t.Context()))
	defer cancel()
	subject, err := protocol.AgentObservationSubject("gru", testNATSUserKey("node-a"), "desired")
	if err != nil {
		t.Fatal(err)
	}
	traceparents := make(chan string, 1)
	sub, err := conn.Subscribe(subject, func(msg *nats.Msg) {
		traceparents <- msg.Header.Get("traceparent")
		cancel()
	})
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = sub.Unsubscribe() })
	if err := conn.Flush(); err != nil {
		t.Fatal(err)
	}
	var out any
	if err := exchange(ctx, conn, "gru", nil, request{Operation: "desired", NATSUserPublicKey: testNATSUserKey("node-a")}, &out); err == nil {
		t.Fatal("request returned without a controller reply")
	}
	if got := <-traceparents; len(got) != 55 || got[3:35] != observability.TraceID(ctx) {
		t.Fatalf("request traceparent = %q, want trace %q", got, observability.TraceID(ctx))
	}
}

func exchange(ctx context.Context, conn *nats.Conn, cell string, controllerKey ed25519.PublicKey, r request, out any) error {
	return exchangeWithEnvelope(ctx, conn, cell, controllerKey, r, out, nil)
}

func exchangeWithEnvelope(ctx context.Context, conn *nats.Conn, cell string, controllerKey ed25519.PublicKey,
	r request, out any, signedOut *protocol.Envelope,
) error {
	if conn == nil {
		return errors.New("NATS connection is required")
	}
	data, err := protocol.EncodeJSON(r.Envelope)
	if err != nil {
		return err
	}
	if len(data) > 64<<10 {
		return errors.New("host request is too large")
	}
	subject, err := protocol.AgentObservationSubject(cell, r.NATSUserPublicKey, r.Operation)
	if err != nil {
		return err
	}
	timeout := 5 * time.Second
	if r.Operation == "material" || r.Operation == "function-material" || r.Operation == "volume-init" || r.Operation == "runtime-effect" || r.Operation == "container-material" || r.Operation == "registry-admission" {
		timeout = 30 * time.Second
	}
	deadline, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()
	msg, err := conn.RequestMsgWithContext(deadline, &nats.Msg{Subject: subject, Data: data, Header: observability.TraceHeader(ctx, nil)})
	if err != nil {
		return err
	}
	if len(msg.Data) > 512<<10 {
		return errors.New("host response is too large")
	}
	var signed protocol.Envelope
	if err := protocol.DecodeStrict(msg.Data, &signed, 512<<10); err != nil {
		return err
	}
	if err := protocol.VerifyEnvelope(signed, protocol.EnvelopeScope{Region: cell, Kind: "host.response." + r.Operation, Actor: "controller", OperationID: entityid.Derive("host-request", r.Nonce), Epoch: r.Epoch}, controllerKey, time.Now().UTC(), protocol.VerifyPolicy{MaxLifetime: requestTTL, ClockSkew: maxClockSkew}); err != nil {
		return err
	}
	var result response
	if err := decodeStrict([]byte(signed.Payload), &result); err != nil {
		return err
	}
	if result.Nonce != r.Nonce || result.Node != r.Node || result.SessionID != r.SessionID || result.Epoch != r.Epoch || result.Operation != r.Operation {
		return errors.New("host response binding mismatch")
	}
	if result.Error != "" {
		if strings.HasPrefix(result.Error, authority.ErrNotLeader.Error()) {
			return fmt.Errorf("%w: %s", errControllerNotLeader, result.Error)
		}
		if result.Retryable {
			if result.Error == errSessionContention.Error() {
				return errSessionContention
			}
			if r.Operation == "session" {
				return fmt.Errorf("%w: %s", errSessionBackendUnavailable, result.Error)
			}
			return errArtifactPreparing
		}
		if r.Operation == "session" {
			if result.Error == errSessionOwned.Error() {
				return errSessionOwned
			}
			return fmt.Errorf("%w: %s", errSessionRequestDenied, result.Error)
		}
		return fmt.Errorf("host request denied: %s", result.Error)
	}
	if out != nil {
		if err := decodeStrict(result.Payload, out); err != nil {
			return err
		}
	}
	if signedOut != nil {
		*signedOut = signed
	}
	return nil
}

func StartTrace(ctx context.Context) context.Context {
	id := ulid.MustParse(entityid.New())
	return context.WithValue(ctx, traceKey{}, hex.EncodeToString(id[:]))
}

func TraceID(ctx context.Context) string {
	trace, _ := ctx.Value(traceKey{}).(string)
	return trace
}

func Traceparent(ctx context.Context) string {
	trace := TraceID(ctx)
	if trace == "" {
		return ""
	}
	var span [8]byte
	for span == [8]byte{} {
		_, _ = rand.Read(span[:])
	}
	return "00-" + trace + "-" + hex.EncodeToString(span[:]) + "-01"
}

func TraceHeader(ctx context.Context, header nats.Header) nats.Header {
	traceparent := Traceparent(ctx)
	if traceparent == "" {
		return header
	}
	if header == nil {
		header = nats.Header{}
	}
	header.Set(traceparentHeader, traceparent)
	return header
}

func AgentObservationSubject(region, userPublicKey, observation string) (string, error) {
	if !nkeys.IsValidPublicUserKey(userPublicKey) {
		return "", ErrInvalidSubjectToken
	}
	root, err := RegionalRoot(region)
	if err != nil {
		return "", err
	}
	if err := ValidateSubjectToken(observation); err != nil {
		return "", err
	}
	return root + ".agent." + userPublicKey + ".observation." + observation, nil
}

func testNATSUserKey(node string) string {
	seed := sha256.Sum256([]byte("host-test-user:" + node))
	pair, err := nkeys.FromRawSeed(nkeys.PrefixByteUser, seed[:])
	if err != nil {
		panic(err)
	}
	defer pair.Wipe()
	public, err := pair.PublicKey()
	if err != nil {
		panic(err)
	}
	return public
}

