func (a *Agent) tsAuthReplica(d Desired) bool {
	return a.cfg.TSAuthRoot != "" && d.Role == tsauth.Role && d.ManagedMember == nil && !d.Withdrawn
}

func (a *Agent) tsAuthMisplaced(d Desired) bool {
	return a.cfg.TSAuthRoot == "" && d.Role == tsauth.Role && d.ManagedMember == nil && !d.Withdrawn
}

