	for i, key := range tsauth.Generated {
		secrets[key] = base64.StdEncoding.EncodeToString([]byte(strings.Repeat(string(rune('a'+i)), 32)))
	}
	return secrets
}

func tsAuthTestDesired() Desired {
	secrets := map[string]vaultsecret.Ref{}
	for _, key := range tsauth.Secrets {
		secrets[key] = vaultsecret.Ref{Vault: tsAuthTestVault, Name: vaultsecret.Name("gru-1", key)}
	}
	return Desired{Cell: "gru", Role: tsauth.Role, Digest: "d", Env: map[string]string{
		tsauth.EnvPublicOrigin: tsauth.PublicOrigin("gru"), tsauth.EnvAPIURL: tsauth.APIURL("gru"), tsauth.EnvDatabase: tsauth.Database,
		tsauth.EnvAudiences: tsauth.APIURL("gru"), tsauth.EnvDashboardRedirectURIs: tsauth.DashboardRedirectURI,
		tsauth.EnvDashboardLogoutURIs: tsauth.DashboardLogoutURI}, Secrets: secrets}
}

func tsAuthTestAgent(t *testing.T) *Agent {
	t.Helper()
	root := filepath.Join(traversableTempDir(t), "ts-auth")
	identity := WorkloadIdentity{UID: uint32(os.Getuid()), GID: uint32(os.Getgid())}
	return &Agent{terraBase: map[string]terraBaseMember{}, cfg: AgentConfig{TSAuthRoot: root, WorkloadIdentity: identity,
		InstallRoot: "/var/lib/host/install", StateRoot: "/var/lib/host/state"}}
}

func traversableTempDir(t *testing.T) string {
	t.Helper()
	dir, err := os.MkdirTemp("/tmp", "ts-terrabase-root-")
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = os.RemoveAll(dir) })
	if err := os.Chmod(dir, 0o755); err != nil {
		t.Fatal(err)
	}
	return dir
}

auth_prepare.text:
func (a *Agent) prepareTSAuth(d Desired, secrets map[string]string) (map[string]string, error) {
	if err := tsauth.ValidateProfile(d.Cell, d.Args, d.Env, d.Secrets); err != nil {
		return nil, err
	}
	if err := tsauth.ValidateSecrets(secrets); err != nil {
		return nil, err
	}
	root, identity := a.cfg.TSAuthRoot, a.cfg.WorkloadIdentity
	// Recheck the ancestors right before the privileged effects below.
	if err := validateWorkloadRoot("ts-auth", root, identity, a.cfg.InstallRoot, a.cfg.StateRoot, a.cfg.TerraBaseRoot); err != nil {
		return nil, err
	}
	layout := tsauth.Layout(root)
	if err := ensureOwnedDir(root, os.Geteuid(), int(identity.GID), 0o750); err != nil {
		return nil, err
	}
	if err := ensureOwnedDir(layout.Bundle(), int(identity.UID), int(identity.GID), 0o700); err != nil {
		return nil, err
	}
	return layout.Env(d.Env, secrets, a.tsAuthPort()), nil
}

func (a *Agent) tsAuthPort() int {
	if a.cfg.TSAuthPort != 0 {
		return a.cfg.TSAuthPort
	}
	return tsauth.Port
}

func ValidateProfile(cell string, args []string, env map[string]string, secrets map[string]vaultsecret.Ref) error {
	if _, ok := catalog.LookupName(cell); !ok {
		return fmt.Errorf("ts-auth needs a catalog cell, not %q", cell)
	}
	if len(args) != 0 {
		return errors.New("ts-auth profile sets its settings only through env")
	}
	if slices.ContainsFunc(Secrets, func(key string) bool { _, ok := secrets[key]; return !ok }) {
		return fmt.Errorf("ts-auth profile secrets must name %s", strings.Join(Secrets, ", "))
	}
	for key := range secrets {
		if !slices.Contains(Secrets, key) && !slices.Contains(OptionalSecrets, key) {
			return fmt.Errorf("ts-auth profile secrets may add only %s, not %s", strings.Join(OptionalSecrets, ", "), key)
		}
	}
	for _, key := range slices.Concat(Secrets, OptionalSecrets, optionalSecrets, []string{EnvListen, EnvBundleExtract}) {
		if _, set := env[key]; set {
			return fmt.Errorf("ts-auth profile must not set %s", key)
		}
	}
	for key, want := range map[string]string{EnvPublicOrigin: PublicOrigin(cell), EnvAPIURL: APIURL(cell), EnvDatabase: Database, EnvAudiences: APIURL(cell),
		EnvDashboardRedirectURIs: DashboardRedirectURI, EnvDashboardLogoutURIs: DashboardLogoutURI} {
		if env[key] != want {
			return fmt.Errorf("ts-auth profile must set %s=%s", key, want)
		}
	}
	return nil
}

func (l Layout) Env(profile, secrets map[string]string, port int) map[string]string {
	env := maps.Clone(profile)
	if env == nil {
		env = map[string]string{}
	}
	maps.Copy(env, secrets)
	env[EnvDatabase] = secrets[EnvProjectID] + "/" + profile[EnvDatabase]
	delete(env, EnvProjectID)
	env[EnvListen] = "http://0.0.0.0:" + strconv.Itoa(port)
	env[EnvBundleExtract] = l.Bundle()
	return env
}

func ValidateSecrets(secrets map[string]string) error {
	for key, value := range secrets {
		if !slices.Contains(Secrets, key) && (!slices.Contains(OptionalSecrets, key) || value == "") {
			return fmt.Errorf("ts-auth needs %s and may add only non-empty %s, not %s",
				strings.Join(Secrets, ", "), strings.Join(OptionalSecrets, ", "), key)
		}
	}
	for _, key := range Secrets {
		if err := validSecret(key, secrets[key]); err != nil {
			return err
		}
	}
	return nil
}

func validSecret(key, value string) error {
	if slices.Contains(Generated, key) {
		decoded, err := base64.StdEncoding.Strict().DecodeString(value)
		// Strict still skips CR and LF; only the canonical form fits one line.
		if err != nil || len(decoded) != 32 || base64.StdEncoding.EncodeToString(decoded) != value {
			return fmt.Errorf("%s must be 32 bytes in base64", key)
		}
		return nil
	}
	if slices.ContainsFunc(Projects, func(project Project) bool { return project.ProjectIDKey == key }) {
		if !entityid.Valid(value) {
			return fmt.Errorf("%s must be a canonical uppercase ULID", key)
		}
		return nil
	}
	if !slices.ContainsFunc(Projects, func(project Project) bool { return project.APIKeyKey == key }) ||
		len(value) > 4096 || !apiKeyRE.MatchString(value) {
		return fmt.Errorf("%s must be 1 to 4096 printable characters without spaces", key)
	}
	return nil
}

func validateWorkloadRoot(name, root string, identity WorkloadIdentity, others ...string) error {
	separator := string(filepath.Separator)
	for _, other := range others {
		if other != "" && (root == other || strings.HasPrefix(root, other+separator) || strings.HasPrefix(other, root+separator)) {
			return errors.New(name + " root must be separate from the install, state and other workload roots")
		}
	}
	if !filepath.IsAbs(root) || filepath.Clean(root) != root || root == separator {
		return errors.New(name + " root must be a clean absolute path other than /")
	}
	// Only the workload root may be absent; every parent must already be safe.
	if err := inspectWorkloadPath(filepath.Dir(root), identity, true, false, false); err != nil {
		return fmt.Errorf("%s root parent: %w", name, err)
	}
	// Every existing component is a real, non-replaceable directory...
	if err := inspectWorkloadPath(root, identity, true, true, false); err != nil {
		return fmt.Errorf("%s root: %w", name, err)
	}
	// ...and the workload cannot create the root before the agent does, not
	// even in a sticky parent such as /tmp.
	if info, err := os.Lstat(filepath.Dir(root)); err == nil && identity.UID != uint32(os.Geteuid()) {
		owner, _ := info.Sys().(*syscall.Stat_t)
		write := info.Mode().Perm() & 0o002
		if owner != nil && owner.Gid == identity.GID {
			write = info.Mode().Perm() & 0o020
		}
		if owner != nil && owner.Uid == identity.UID {
			write = info.Mode().Perm() & 0o200
		}
		if write != 0 {
			return errors.New("the workload identity can create entries next to the " + name + " root")
		}
	}
	// ...so the path resolves to itself.
	existing := root
	for {
		if _, err := os.Lstat(existing); err == nil {
			break
		}
		existing = filepath.Dir(existing)
	}
	if resolved, err := filepath.EvalSymlinks(existing); err != nil || resolved != existing {
		return fmt.Errorf("%s root %s does not resolve to itself", name, existing)
	}
	return nil
}

func ensureOwnedDir(path string, uid, gid int, mode os.FileMode) error {
	if err := os.Mkdir(path, mode); err != nil && !errors.Is(err, os.ErrExist) {
		return err
	}
	fd, err := unix.Open(path, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_NOFOLLOW|unix.O_CLOEXEC, 0)
	if err != nil {
		return fmt.Errorf("%s must be a directory, not a symlink: %w", path, err)
	}
	defer unix.Close(fd)
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil {
		return err
	}
	if int(stat.Uid) == uid && int(stat.Gid) == gid && stat.Mode&0o7777 == uint32(mode.Perm()) {
		return nil
	}
	if err := unix.Fchown(fd, os.Geteuid(), gid); err != nil {
		return err
	}
	if err := unix.Fchmod(fd, uint32(mode.Perm())); err != nil {
		return err
	}
	return unix.Fchown(fd, uid, gid)
}

func inspectWorkloadPath(path string, identity WorkloadIdentity, tenantTraverse, allowMissing, privateState bool) error {
	current := string(filepath.Separator)
	for _, part := range strings.Split(strings.TrimPrefix(path, current), current) {
		if part != "" {
			current = filepath.Join(current, part)
		}
		info, err := os.Lstat(current)
		if err != nil {
			if allowMissing && errors.Is(err, os.ErrNotExist) {
				return nil
			}
			return fmt.Errorf("inspect %s: %w", current, err)
		}
		if !info.IsDir() || info.Mode()&os.ModeSymlink != 0 {
			return fmt.Errorf("%s must be a directory without symlinks", current)
		}
		owner, ok := info.Sys().(*syscall.Stat_t)
		if !ok {
			return fmt.Errorf("cannot inspect owner of %s", current)
		}
		if os.Geteuid() == 0 && owner.Uid != 0 {
			return fmt.Errorf("host path ancestor %s must be root-owned", current)
		}
		permissions := info.Mode().Perm()
		search := permissions & 0001
		write := permissions & 0002
		if owner.Gid == identity.GID {
			search, write = permissions&0010, permissions&0020
		}
		if owner.Uid == identity.UID {
			search, write = permissions&0100, permissions&0200
		}
		if tenantTraverse && search == 0 {
			return fmt.Errorf("workload identity cannot traverse %s", current)
		}
		if privateState && os.Geteuid() == 0 && permissions&0022 != 0 {
			return fmt.Errorf("state path ancestor %s is group- or world-writable", current)
		}
		if identity.UID != uint32(os.Geteuid()) && write != 0 &&
			(privateState || info.Mode()&os.ModeSticky == 0 || owner.Uid != 0) {
			return fmt.Errorf("workload identity can replace host path under %s", current)
		}
	}
	return nil
}

auth_desired.text:
func validateDesired(d Desired, cell string, r Registration) error {
	if d.Cell != cell || d.Node != r.Node || d.Environment != r.Environment {
		return errors.New("desired identity mismatch")
	}
	if err := validateToken(d.Role, "role"); err != nil {
		return err
	}
	if !slices.Contains(r.Roles, d.Role) {
		return errors.New("role is not registered")
	}
	if (r.ManagedOCI == nil) != (d.ManagedMember == nil) {
		return errors.New("managed desired and registration kind differ")
	}
	if d.ManagedMember != nil {
		if r.ManagedMember == nil {
			return errors.New("managed registration lacks member binding")
		}
		if d.Role != "terrabase" || *r.ManagedOCI != d.ManagedMember.OCI ||
			*r.ManagedMember != d.ManagedMember.Member {
			return errors.New("managed desired binding differs from registration")
		}
		if err := validateManagedMemberLaunch(*d.ManagedMember, d, r); err != nil {
			return err
		}
	}
	if d.Generation == 0 {
		return errors.New("desired generation must be positive")
	}
	if d.Withdrawn {
		if d.Digest != "" || len(d.Args) != 0 || len(d.Env) != 0 || len(d.Secrets) != 0 {
			return errors.New("withdrawn desired contains execution data")
		}
	} else if err := validateDigest(d.Digest); err != nil {
		return err
	}
	if len(d.Args) > 64 || len(d.Env) > 64 {
		return errors.New("too many workload arguments or environment variables")
	}
	for _, arg := range d.Args {
		if len(arg) > 4096 {
			return errors.New("argument too long")
		}
	}
	for key, value := range d.Env {
		if !regexp.MustCompile(`^[A-Za-z_][A-Za-z0-9_]*$`).MatchString(key) || len(value) > 4096 {
			return errors.New("invalid workload environment")
		}
	}
	// A C# TerraBase member's environment is host-owned: it takes only
	// secret files, whose paths the host sets.
	for key := range d.Secrets {
		if d.Role == terrabase.Role && !vaultsecret.FileKey(key) {
			return errors.New("terrabase takes only Vault secret files (keys ending in _FILE)")
		}
		if roleidentity.Reserved(d.Role, key) {
			return fmt.Errorf("the host sets %s for %s's NATS identity", key, d.Role)
		}
	}
	for key := range d.Env {
		if roleidentity.Reserved(d.Role, key) {
			return fmt.Errorf("the host sets %s for %s's NATS identity", key, d.Role)
		}
	}
	return vaultsecret.ValidateRefs(d.Cell, d.Role, d.Secrets, d.Env)
}

func ValidateRefs(cell, role string, refs map[string]Ref, env map[string]string) error {
	if len(refs) > MaxRefs {
		return fmt.Errorf("%s has more than %d Vault secrets", role, MaxRefs)
	}
	if len(refs) != 0 && slices.ContainsFunc(infrastructure, func(family string) bool {
		return role == family || strings.HasPrefix(role, family+"-") || strings.HasPrefix(family, role+"-")
	}) {
		return fmt.Errorf("role %s shares a name with the cell's infrastructure secrets and names no Vault secrets", role)
	}
	return ValidateDeliveryRefs(cell, role, refs, env)
}

func ValidateDeliveryRefs(cell, service string, refs map[string]Ref, env map[string]string) error {
	if len(refs) > MaxRefs || !nameRE.MatchString(service) {
		return errors.New("Vault delivery needs a service name and at most 64 references")
	}
	entry, known := catalog.LookupName(cell)
	files := map[string]bool{}
	for key, ref := range refs {
		if !known || ref.region() != entry.OCIRegion {
			return fmt.Errorf("Vault secret %s of %s must name a Vault in cell %s's region", key, service, cell)
		}
		if !envKeyRE.MatchString(key) {
			return fmt.Errorf("Vault secret key %q of %s is not an environment name", key, service)
		}
		if _, set := env[key]; set {
			return fmt.Errorf("%s sets %s both in env and as a Vault secret", service, key)
		}
		if files[strings.ToLower(key)] {
			return errors.New("Vault secret keys must name distinct files after lowercasing")
		}
		files[strings.ToLower(key)] = true
		rest, inCell := strings.CutPrefix(ref.Name, cell+"-")
		secretKey, ofService := strings.CutPrefix(rest, service+"-")
		if !ofService {
			// Existing signed profiles retain their cell-number namespace.
			index, legacy, _ := strings.Cut(rest, "-")
			secretKey, ofService = strings.CutPrefix(legacy, service+"-")
			ofService = ofService && index != "" && index[0] != '0' && strings.Trim(index, "0123456789") == ""
		}
		if len(ref.Name) > 255 || !nameRE.MatchString(ref.Name) || !inCell || !ofService || secretKey == "" {
			return fmt.Errorf("Vault secret %s of %s must name %s-%s-<purpose> or an existing %s-<n>-%s-<purpose>", key, service, cell, service, cell, service)
		}
	}
	return nil
}
